<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {request,isRequestCanceled} from '../api/client';import type {Response} from '../api/client';import DataTable from './DataTable.vue';import {usePlatform} from '../stores/platform';
const props=defineProps<{taskId:string}>(),p=usePlatform(),task=ref<Response<'getTask'>['data']>(),errors=ref<Response<'listTaskRowErrors'>['data']['items']>([]),result=ref<Response<'getImportTaskResult'>['data']>(),error=ref(''),errorCursor=ref<string|null>(null),resultCursor=ref<string|null>(null),busy=ref(false),controller=new AbortController();
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){if(!isRequestCanceled(e))error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function rowErrors(next=false){const r=(await request('listTaskRowErrors',{path:{taskId:props.taskId},query:{pageSize:100,cursor:next?errorCursor.value||undefined:undefined},signal:controller.signal})).data;errors.value=next?[...errors.value,...r.items]:r.items;errorCursor.value=r.nextCursor;}
async function importResult(next=false){const r=(await request('getImportTaskResult',{path:{taskId:props.taskId},query:{pageSize:100,cursor:next?resultCursor.value||undefined:undefined},signal:controller.signal})).data;result.value=next&&result.value?{...r,items:[...result.value.items,...r.items]}:r;resultCursor.value=r.nextCursor;}
async function refresh(){await run(async()=>{task.value=(await request('getTask',{path:{taskId:props.taskId},signal:controller.signal})).data;errors.value=[];result.value=undefined;if(['DATASET_IMPORT','PERSON_LIBRARY_IMPORT','DEVICE_IMPORT','INGESTION'].includes(task.value.taskType)){if(task.value.status==='FAILED')await rowErrors();if(task.value.status==='SUCCESS'&&task.value.taskType!=='INGESTION')await importResult();}});}
async function action(id:'cancelTask'|'retryTask'){await run(async()=>{await request(id,{path:{taskId:props.taskId},signal:controller.signal});});await refresh();}
async function openSetResult(){await run(async()=>{const id=task.value?.resultReference?.resultId;if(!id)throw new Error('任务没有集合结果编号');const result=(await request('getSetTask',{path:{setTaskId:id},signal:controller.signal})).data;if(result.task.status!=='SUCCESS'||!result.resultDatasetId)throw new Error('运算结果尚未生成');p.selectedDataset=result.resultDatasetId;p.navigate('数据运算');});}
onMounted(refresh);onBeforeUnmount(()=>controller.abort());
</script>
<template><el-alert v-if="error" type="error" :title="error" :closable="false"/><template v-if="task"><h3>{{task.name}}</h3><p>状态 {{task.status}} · 类型 {{task.taskType}}</p><el-progress :percentage="task.progress"/><p v-if="task.errorMessage">{{task.errorCode}}：{{task.errorMessage}}</p><p class="muted">Trace ID：{{task.traceId}}</p><div class="actions"><el-button :loading="busy" @click="refresh">刷新状态</el-button><el-button v-if="['PENDING','QUEUED','RUNNING'].includes(task.status)" :loading="busy" @click="action('cancelTask')">请求取消任务</el-button><el-button v-if="task.status==='FAILED'" :loading="busy" @click="action('retryTask')">重试失败任务</el-button><el-button v-if="task.status==='SUCCESS'&&task.resultReference?.resultType==='SET_OPERATION'" @click="openSetResult">查看运算结果数据集</el-button><el-button v-if="task.status==='SUCCESS'&&task.resultReference?.fileAssetId" @click="p.downloadTask(task.taskId)">下载任务结果</el-button></div><DataTable v-if="errors.length" :rows="errors.map((r,i)=>({...r,id:String(i)}))" :columns="[{key:'rowNumber',label:'错误行号'},{key:'field',label:'字段'},{key:'code',label:'错误码'},{key:'reason',label:'原因'}]" :selectable="false" title="导入校验错误"/><el-button v-if="errorCursor" @click="run(()=>rowErrors(true))">加载更多错误</el-button><template v-if="result"><p>已导入 {{result.importedCount}} 行 · 跳过 {{result.skippedCount}} 行</p><DataTable :rows="result.items.map((r,i)=>({...r,id:String(i)}))" :columns="[{key:'rowNumber',label:'导入行号'},{key:'status',label:'处理状态'},{key:'datasetId',label:'数据集'},{key:'deviceId',label:'设备'},{key:'libraryId',label:'人员库'},{key:'memberId',label:'成员'}]" :selectable="false" title="导入结果"/><el-button v-if="resultCursor" @click="run(()=>importResult(true))">加载更多导入结果</el-button></template></template></template>
